import React, { useEffect, useState, useRef } from 'react';
import { Card, CardHeader, Table, Btn, Badge, Modal, FormRow, FormField, SearchBar, Spinner } from '../components/ui/Card';
import api from '../utils/api';
import toast from 'react-hot-toast';
import { useAuth } from '../contexts/AuthContext';
import { useLang } from '../i18n/LanguageContext';

const SERVICES = ['Direction','Administration','Logistique','Communication','Mobilisation','Technique'];
const CONTRATS = ['CDI','CDD','Bénévole','Stage','Autre'];
const STATUTS_FAMILLE = ['Célibataire','Marié(e)','Divorcé(e)','Veuf/Veuve'];

const defaultForm = {
  nom:'', prenom:'', nom_jeune_fille:'', date_naissance:'', lieu_naissance:'',
  adresse:'', telephone:'', email:'', situation_familiale:'Célibataire',
  contact_urgence_nom:'', contact_urgence_tel:'',
  cin_numero:'', cin_date:'', cin_lieu:'',
  rib_code:'', banque:'',
  poste:'', service:'Administration', type_contrat:'CDI', date_entree:'',
  superieur:'', cnaps:'', aro:'', statut:'actif',
  photo:'',
  doc_diplome:'', doc_cv:'', doc_contrat:''
};

// ── PHOTO UPLOAD ─────────────────────────────────────────────
function PhotoUpload({ value, onChange, t }) {
  const ref = useRef();
  const handleFile = e => {
    const file = e.target.files[0]; if (!file) return;
    if (file.size > 2*1024*1024) { toast.error(t('personnel.photoTooBig')); return; }
    const reader = new FileReader();
    reader.onload = ev => onChange(ev.target.result);
    reader.readAsDataURL(file);
  };
  return (
    <div style={{ display:'flex', flexDirection:'column', alignItems:'center', gap:10 }}>
      <div onClick={() => ref.current.click()} style={{ width:110, height:120, borderRadius:12, border:'2px dashed var(--gold)', background:value?'transparent':'var(--gray-50)', cursor:'pointer', overflow:'hidden', display:'flex', alignItems:'center', justifyContent:'center' }}>
        {value
          ? <img src={value} alt="Photo" style={{ width:'100%', height:'100%', objectFit:'cover' }} />
          : <div style={{ textAlign:'center', color:'var(--gray-400)', fontSize:'0.75rem' }}>
              <div style={{ fontSize:'2rem', marginBottom:4 }}>📷</div>
              <span>{t('personnel.photoHint')}</span>
            </div>}
      </div>
      <input ref={ref} type="file" accept="image/*" onChange={handleFile} style={{ display:'none' }} />
      <div style={{ display:'flex', gap:6 }}>
        <button type="button" onClick={() => ref.current.click()} style={{ fontSize:'0.72rem', padding:'4px 10px', border:'1px solid var(--gold)', borderRadius:6, background:'transparent', color:'var(--gold-dark)', cursor:'pointer', fontWeight:600 }}>
          {value ? t('personnel.changePhoto') : t('personnel.addPhoto')}
        </button>
        {value && <button type="button" onClick={() => onChange('')} style={{ fontSize:'0.72rem', padding:'4px 10px', border:'1px solid var(--gray-200)', borderRadius:6, background:'transparent', color:'var(--gray-500)', cursor:'pointer' }}>{t('personnel.removePhoto')}</button>}
      </div>
    </div>
  );
}

// ── DOCUMENT UPLOAD ───────────────────────────────────────────
function DocUpload({ label, value, onChange, t }) {
  const ref = useRef();
  const handleFile = e => {
    const file = e.target.files[0]; if (!file) return;
    if (file.size > 10*1024*1024) { toast.error(t('personnel.docTooBig')); return; }
    const reader = new FileReader();
    reader.onload = ev => onChange({ data: ev.target.result, name: file.name, type: file.type });
    reader.readAsDataURL(file);
  };
  const docData = typeof value === 'object' ? value : (value ? { data: value, name: label + '.pdf', type: 'application/pdf' } : null);

  return (
    <div style={{ border:'1px solid var(--gray-200)', borderRadius:10, padding:'12px 14px', background:'var(--gray-50)' }}>
      <p style={{ fontSize:'0.75rem', fontWeight:700, color:'var(--navy)', marginBottom:8 }}>{label}</p>
      {docData?.data ? (
        <div style={{ display:'flex', alignItems:'center', gap:8, flexWrap:'wrap' }}>
          <span style={{ fontSize:'0.78rem', color:'var(--gray-600)', flex:1, minWidth:0, overflow:'hidden', textOverflow:'ellipsis', whiteSpace:'nowrap' }}>
            📄 {docData.name}
          </span>
          <div style={{ display:'flex', gap:6, flexShrink:0 }}>
            <button type="button" onClick={() => { const w = window.open(); w.document.write(`<iframe src="${docData.data}" style="width:100%;height:100vh;border:none"></iframe>`); }} style={{ fontSize:'0.72rem', padding:'4px 10px', border:'1px solid var(--navy)', borderRadius:6, background:'transparent', color:'var(--navy)', cursor:'pointer', fontWeight:600 }}>{t('personnel.viewDoc')}</button>
            <a href={docData.data} download={docData.name} style={{ fontSize:'0.72rem', padding:'4px 10px', border:'1px solid var(--gold)', borderRadius:6, background:'transparent', color:'var(--gold-dark)', cursor:'pointer', fontWeight:600, textDecoration:'none' }}>{t('common.download')}</a>
            <button type="button" onClick={() => onChange('')} style={{ fontSize:'0.72rem', padding:'4px 10px', border:'1px solid #fca5a5', borderRadius:6, background:'transparent', color:'#dc2626', cursor:'pointer' }}>{t('personnel.deleteDoc')}</button>
          </div>
        </div>
      ) : (
        <button type="button" onClick={() => ref.current.click()} style={{ width:'100%', padding:'8px', border:'2px dashed var(--gray-300)', borderRadius:8, background:'white', cursor:'pointer', color:'var(--gray-400)', fontSize:'0.78rem', display:'flex', alignItems:'center', justifyContent:'center', gap:6 }}>
          📎 {t('personnel.uploadDoc')}
        </button>
      )}
      <input ref={ref} type="file" accept=".pdf,.doc,.docx,image/*" onChange={handleFile} style={{ display:'none' }} />
    </div>
  );
}

// ── PRINT LIST ────────────────────────────────────────────────
function printList(data, filterService, lang) {
  const now = new Date().toLocaleDateString(lang === 'fr' ? 'fr-FR' : 'en-GB', { year:'numeric', month:'long', day:'numeric' });
  const w = window.open('','_blank','width=1200,height=750');
  w.document.write(`<!DOCTYPE html><html lang="${lang}"><head><meta charset="UTF-8"/>
<title>${lang==='fr'?'Liste du Personnel':'Staff List'} — LHM Madagascar</title>
<style>
@page{size:A4 landscape;margin:12mm 10mm}
*{box-sizing:border-box;margin:0;padding:0}
body{font-family:Arial,sans-serif;font-size:10px;color:#222}
.hdr{display:flex;align-items:center;gap:14px;margin-bottom:14px;padding-bottom:10px;border-bottom:3px solid #0f2044}
.hdr img{height:44px;object-fit:contain}
.hdr h1{font-size:15px;color:#0f2044;font-weight:700}
.hdr p{font-size:10px;color:#666;margin-top:2px}
.stats{display:flex;gap:14px;margin-bottom:12px}
.stat{background:#f0f4ff;border:1px solid #dbeafe;border-radius:8px;padding:7px 12px}
.stat-n{font-size:18px;font-weight:700;color:#0f2044}
.stat-l{font-size:9px;color:#6b7280}
table{width:100%;border-collapse:collapse}
thead tr{background:#0f2044;color:white}
th{padding:6px 8px;text-align:left;font-size:9px;font-weight:600}
tbody tr:nth-child(even){background:#f8faff}
td{padding:5px 7px;border-bottom:1px solid #e5e7eb;vertical-align:middle}
