</style></head><body>
<div class="hdr">
  <img src="${window.location.origin}/logo-lhm.png" onerror="this.style.display='none'" alt="LHM"/>
  <div>
    <h1>${lang==='fr'?'Liste du Personnel':'Staff List'} — LHM Madagascar</h1>
    <p>${filterService?(lang==='fr'?'Service : ':'Department: ')+filterService:(lang==='fr'?'Tous les services':'All departments')} &nbsp;|&nbsp; ${lang==='fr'?'Imprimé le':'Printed on'} ${now}</p>
  </div>
</div>
<div class="stats">
  <div class="stat"><div class="stat-n">${data.length}</div><div class="stat-l">${lang==='fr'?'Total':'Total'}</div></div>
  <div class="stat"><div class="stat-n">${data.filter(p=>p.statut==='actif').length}</div><div class="stat-l">${lang==='fr'?'Actifs':'Active'}</div></div>
  <div class="stat"><div class="stat-n">${[...new Set(data.map(p=>p.service))].length}</div><div class="stat-l">${lang==='fr'?'Services':'Departments'}</div></div>
</div>
<table>
<thead><tr>
  <th>${lang==='fr'?'Photo':'Photo'}</th>
  <th>${lang==='fr'?'Matricule':'ID'}</th>
  <th>${lang==='fr'?'Nom & Prénom':'Name'}</th>
  <th>${lang==='fr'?'CIN':'ID Card'}</th>
  <th>${lang==='fr'?'Téléphone':'Phone'}</th>
  <th>${lang==='fr'?'Poste':'Position'}</th>
  <th>${lang==='fr'?'Service':'Dept.'}</th>
  <th>${lang==='fr'?'Contrat':'Contract'}</th>
  <th>${lang==='fr'?'Date Entrée':'Start Date'}</th>
  <th>${lang==='fr'?'RIB':'RIB'}</th>
  <th>${lang==='fr'?'CNAPS':'CNAPS'}</th>
  <th>${lang==='fr'?'Statut':'Status'}</th>
</tr></thead>
<tbody>${data.map(p=>`<tr>
  <td>${p.photo?`<img class="photo" src="${p.photo}" alt="photo"/>`:'<div class="nophoto">👤</div>'}</td>
  <td class="mat">${p.matricule||'—'}</td>
  <td><div class="nom">${p.prenom||''} ${p.nom||''}</div><div class="sub">${p.email||''}</div></td>
  <td>${p.cin_numero||'—'}</td>
  <td>${p.telephone||'—'}</td>
  <td>${p.poste||'—'}</td>
  <td>${p.service||'—'}</td>
  <td>${p.type_contrat||'—'}</td>
  <td>${p.date_entree?new Date(p.date_entree).toLocaleDateString('fr-FR'):'—'}</td>
  <td style="font-family:monospace">${p.rib_code||'—'}</td>
  <td>${p.cnaps||'—'}</td>
  <td><span class="badge b-${p.statut}">${p.statut}</span></td>
</tr>`).join('')}</tbody>
</table>
<div class="footer">LHM Madagascar — Feon'ny Filazantsara &nbsp;•&nbsp; ${lang==='fr'?'Document confidentiel':'Confidential document'} &nbsp;•&nbsp; ${data.length} ${lang==='fr'?'membre(s)':'member(s)'}</div>
</body></html>`);
  w.document.close();
  w.onload = () => w.print();
}

// ── PRINT FICHE ───────────────────────────────────────────────
function printFiche(p, lang) {
  const now = new Date().toLocaleDateString(lang==='fr'?'fr-FR':'en-GB',{year:'numeric',month:'long',day:'numeric'});
  const w = window.open('','_blank','width=820,height=1100');
  w.document.write(`<!DOCTYPE html><html lang="${lang}"><head><meta charset="UTF-8"/>
<title>${lang==='fr'?'Fiche Personnel':'Staff Card'} — ${p.prenom} ${p.nom}</title>
<style>
@page{size:A4 portrait;margin:14mm}
*{box-sizing:border-box;margin:0;padding:0}
body{font-family:Arial,sans-serif;font-size:10.5px;color:#222}
.hdr{display:flex;align-items:center;justify-content:space-between;margin-bottom:18px;padding-bottom:12px;border-bottom:3px solid #0f2044}
.hdr img{height:44px}
.hdr-c h1{font-size:17px;color:#0f2044;font-weight:700;text-align:center}
.hdr-c p{font-size:9.5px;color:#999;text-align:center;margin-top:2px}
.identity{display:flex;gap:18px;background:linear-gradient(135deg,#0f2044,#1a3a6e);color:white;padding:14px 18px;border-radius:10px;margin-bottom:16px;align-items:center}
.photo-box{width:76px;height:92px;border:2px solid #c9a84c;border-radius:8px;overflow:hidden;display:flex;align-items:center;justify-content:center;background:#1a2e4a;flex-shrink:0}
.photo-box img{width:100%;height:100%;object-fit:cover}
.id-text h2{font-size:17px;font-weight:700}
.id-text p{font-size:10px;opacity:.8;margin-top:3px}
.mat{font-family:monospace;background:rgba(201,168,76,.3);padding:2px 8px;border-radius:4px;font-size:11px;color:#c9a84c;font-weight:700;display:inline-block;margin-top:5px}
.section{margin-bottom:14px}
.sec-title{font-size:9.5px;font-weight:700;color:#c9a84c;text-transform:uppercase;letter-spacing:.08em;margin-bottom:8px;border-bottom:1px solid #e5e7eb;padding-bottom:3px}
.grid{display:grid;grid-template-columns:1fr 1fr;gap:6px 18px}
.field label{font-size:8.5px;color:#9ca3af;text-transform:uppercase;letter-spacing:.05em;display:block;margin-bottom:1px}
.field span{font-size:10.5px;color:#0f2044;font-weight:500}
.footer{margin-top:18px;text-align:center;font-size:9px;color:#9ca3af;border-top:1px solid #e5e7eb;padding-top:7px}
</style></head><body>
<div class="hdr">
  <img src="${window.location.origin}/logo-lhm.png" onerror="this.style.display='none'" alt="LHM"/>
  <div class="hdr-c"><h1>${lang==='fr'?'Fiche du Personnel':'Staff Record'}</h1><p>${lang==='fr'?'Document confidentiel — Imprimé le':'Confidential — Printed on'} ${now}</p></div>
  <div style="width:80px"></div>
</div>
<div class="identity">
  <div class="photo-box">${p.photo?`<img src="${p.photo}" alt="photo"/>`:'<div style="font-size:2.5rem;color:#ccc">👤</div>'}</div>
  <div class="id-text">
    <h2>${p.prenom||''} ${p.nom||''}</h2>
    <p>${p.poste||''} — ${p.service||''}</p>
    <p>${p.email||''} ${p.telephone?'| '+p.telephone:''}</p>
    <div class="mat">${p.matricule||'—'}</div>
  </div>
</div>
<div class="section">
  <div class="sec-title">${lang==='fr'?'A — Informations personnelles':'A — Personal information'}</div>
  <div class="grid">
    <div class="field"><label>${lang==='fr'?'Date de naissance':'Date of birth'}</label><span>${p.date_naissance?new Date(p.date_naissance).toLocaleDateString('fr-FR'):'—'}</span></div>
    <div class="field"><label>${lang==='fr'?'Lieu de naissance':'Place of birth'}</label><span>${p.lieu_naissance||'—'}</span></div>
    <div class="field"><label>${lang==='fr'?'Situation familiale':'Marital status'}</label><span>${p.situation_familiale||'—'}</span></div>
    <div class="field"><label>${lang==='fr'?'Adresse':'Address'}</label><span>${p.adresse||'—'}</span></div>
    <div class="field"><label>${lang==='fr'?'Contact urgence':'Emergency contact'}</label><span>${p.contact_urgence_nom||'—'}</span></div>
    <div class="field"><label>${lang==='fr'?'Tél. urgence':'Emergency phone'}</label><span>${p.contact_urgence_tel||'—'}</span></div>
  </div>
</div>
<div class="section">
  <div class="sec-title">${lang==='fr'?'B — Identité officielle':'B — Official identity'}</div>
  <div class="grid">
    <div class="field"><label>${lang==='fr'?'N° CIN':'ID Card N°'}</label><span>${p.cin_numero||'—'}</span></div>
    <div class="field"><label>${lang==='fr'?'Date délivrance CIN':'CIN issued on'}</label><span>${p.cin_date||'—'}</span></div>
    <div class="field"><label>${lang==='fr'?'Lieu délivrance':'Place of issue'}</label><span>${p.cin_lieu||'—'}</span></div>
    <div class="field"><label>${lang==='fr'?'Code RIB':'RIB code'}</label><span style="font-family:monospace">${p.rib_code||'—'}</span></div>
    <div class="field"><label>${lang==='fr'?'Banque':'Bank'}</label><span>${p.banque||'—'}</span></div>
  </div>
</div>
<div class="section">
  <div class="sec-title">${lang==='fr'?'C — Informations professionnelles':'C — Professional information'}</div>
  <div class="grid">
    <div class="field"><label>${lang==='fr'?'Contrat':'Contract'}</label><span>${p.type_contrat||'—'}</span></div>
    <div class="field"><label>${lang==='fr'?"Date d'entrée":'Start date'}</label><span>${p.date_entree?new Date(p.date_entree).toLocaleDateString('fr-FR'):'—'}</span></div>
    <div class="field"><label>${lang==='fr'?'N° CNAPS':'CNAPS N°'}</label><span>${p.cnaps||'—'}</span></div>
    <div class="field"><label>${lang==='fr'?'N° ARO':'ARO N°'}</label><span>${p.aro||'—'}</span></div>
    <div class="field"><label>${lang==='fr'?'Statut':'Status'}</label><span>${p.statut||'—'}</span></div>
  </div>
</div>
<div class="footer">LHM Madagascar — Feon'ny Filazantsara &nbsp;•&nbsp; ${lang==='fr'?'Fiche confidentielle — Usage interne':'Confidential record — Internal use only'}</div>
</body></html>`);
  w.document.close();
  w.onload = () => w.print();
}

// ── MAIN PAGE ─────────────────────────────────────────────────
export default function PersonnelPage() {
  const { hasRole } = useAuth();
  const { t, lang } = useLang();
  const [personnel, setPersonnel] = useState([]);
  const [loading, setLoading] = useState(true);
  const [search, setSearch] = useState('');
  const [filterService, setFilterService] = useState('');
  const [modalOpen, setModalOpen] = useState(false);
  const [editing, setEditing] = useState(null);
  const [form, setForm] = useState(defaultForm);
  const [saving, setSaving] = useState(false);

  const canEdit = hasRole('super_admin','assistant_admin');

  useEffect(() => {
    const el = document.getElementById('page-title');
    if (el) el.textContent = t('personnel.title');
    loadPersonnel();
  }, [lang]);

  const loadPersonnel = async () => {
    setLoading(true);
    try { const r = await api.get('/personnel'); setPersonnel(r.data.data); }
    catch { toast.error(t('common.error')); }
    finally { setLoading(false); }
  };

  const filtered = personnel.filter(p => {
    const s = search.toLowerCase();
    const matchSearch = !s || p.nom?.toLowerCase().includes(s) || p.prenom?.toLowerCase().includes(s) || p.matricule?.toLowerCase().includes(s) || p.poste?.toLowerCase().includes(s);
    const matchService = !filterService || p.service === filterService;
    return matchSearch && matchService;
  });

  const openModal = (p = null) => {
    setEditing(p);
    setForm(p ? { ...defaultForm, ...p } : defaultForm);
    setModalOpen(true);
  };

  const handleSave = async e => {
    e.preventDefault(); setSaving(true);
    try {
      if (editing) { await api.put(`/personnel/${editing.id}`, form); toast.success(t('common.success')); }
      else { await api.post('/personnel', form); toast.success(t('common.success')); }
      setModalOpen(false); loadPersonnel();
    } catch (err) { toast.error(err.response?.data?.message || t('common.error')); }
    finally { setSaving(false); }
  };

  const handleDeactivate = async id => {
    if (!window.confirm(t('personnel.deactivate'))) return;
    try { await api.delete(`/personnel/${id}`); toast.success(t('personnel.deactivated')); loadPersonnel(); }
    catch { toast.error(t('common.error')); }
  };

  const columns = [
    { key:'photo', header:t('personnel.photo'), render:(v,row) => (
      <div style={{ width:38, height:44, borderRadius:8, overflow:'hidden', border:'1.5px solid var(--gray-200)', background:'var(--gray-100)', display:'flex', alignItems:'center', justifyContent:'center' }}>
        {v ? <img src={v} alt={row.prenom} style={{ width:'100%', height:'100%', objectFit:'cover' }} /> : <span style={{ fontSize:'1.2rem' }}>👤</span>}
      </div>
    )},
    { key:'matricule', header:t('personnel.matricule'), render:v => <span style={{ fontFamily:'monospace', fontWeight:700, color:'var(--navy)', fontSize:'0.82rem' }}>{v}</span> },
    { key:'nom', header:t('personnel.nameAndTitle'), render:(_,row) => (
      <div>
        <p style={{ fontWeight:600, color:'var(--navy)' }}>{row.prenom} {row.nom}</p>
        <p style={{ fontSize:'0.73rem', color:'var(--gray-400)' }}>{row.email}</p>
      </div>
    )},
    { key:'cin_numero', header:t('personnel.cinNumber'), render:v => <span style={{ fontFamily:'monospace', fontSize:'0.82rem' }}>{v||'—'}</span> },
    { key:'poste', header:t('personnel.post') },
    { key:'service', header:t('personnel.service'), render:v => <Badge type="info">{v}</Badge> },
    { key:'type_contrat', header:t('personnel.contract'), render:v => <Badge type="gold">{v}</Badge> },
    { key:'rib_code', header:'RIB', render:v => <span style={{ fontFamily:'monospace', fontSize:'0.8rem', color:'var(--navy)' }}>{v||'—'}</span> },
    { key:'statut', header:t('common.status'), render:v => <Badge type={v==='actif'?'success':'error'}>{v}</Badge> },
    { key:'actions', header:t('common.actions'), render:(_,row) => (
      <div style={{ display:'flex', gap:5, flexWrap:'wrap' }}>
        <Btn size="sm" variant="secondary" onClick={() => printFiche(row, lang)} title={t('personnel.printCard')}>🖨️</Btn>
        <Btn size="sm" variant="secondary" onClick={() => openModal(row)}>✏️</Btn>
        {canEdit && <Btn size="sm" variant="danger" onClick={() => handleDeactivate(row.id)}>🗑️</Btn>}
      </div>
    )}
  ];

  return (
    <div className="animate-fade">
      <Card style={{ marginBottom:20 }}>
        <CardHeader
          title={t('personnel.title')}
          subtitle={`${filtered.length} ${t('personnel.found')}`}
          action={
            <div style={{ display:'flex', gap:8, flexWrap:'wrap' }}>
              <Btn variant="secondary" onClick={() => printList(filtered, filterService, lang)}>🖨️ {t('personnel.printList').replace('🖨️ ','')}</Btn>
              {canEdit && <Btn variant="gold" onClick={() => openModal()}>{t('personnel.newMember')}</Btn>}
            </div>
          }
        />
        <div style={{ display:'flex', gap:12, flexWrap:'wrap' }}>
          <div style={{ flex:1, minWidth:180 }}>
            <SearchBar value={search} onChange={setSearch} placeholder={t('personnel.search')} />
          </div>
          <select value={filterService} onChange={e => setFilterService(e.target.value)} style={{ width:'auto', minWidth:150 }}>
            <option value="">{t('common.allServices')}</option>
            {SERVICES.map(s => <option key={s} value={s}>{s}</option>)}
          </select>
        </div>
      </Card>

      <Card>
        {loading ? <Spinner /> : <Table columns={columns} data={filtered} emptyMessage={t('personnel.noPersonnel')} />}
      </Card>

      {/* ── MODAL ── */}
      <Modal open={modalOpen} onClose={() => setModalOpen(false)} title={editing ? `${t('personnel.editModal')} — ${editing.prenom} ${editing.nom}` : t('personnel.newModal')} width={740}>
        <form onSubmit={handleSave} style={{ padding:'24px' }}>

          {/* ── PHOTO + IDENTIFICATION ── */}
          <div style={{ display:'flex', gap:20, marginBottom:22, paddingBottom:18, borderBottom:'1px solid var(--gray-100)', flexWrap:'wrap' }}>
            <div style={{ minWidth:130, display:'flex', flexDirection:'column', alignItems:'center', gap:6 }}>
              <p style={{ fontSize:'0.72rem', fontWeight:700, color:'var(--gold-dark)', textTransform:'uppercase', letterSpacing:'0.06em' }}>{t('personnel.photoSection')}</p>
              <PhotoUpload value={form.photo} onChange={v => setForm({...form, photo:v})} t={t} />
            </div>
            <div style={{ flex:1, minWidth:200 }}>
              <p style={{ fontSize:'0.72rem', fontWeight:700, color:'var(--gold-dark)', textTransform:'uppercase', letterSpacing:'0.06em', marginBottom:10 }}>{t('personnel.quickId')}</p>
              <FormRow>
                <FormField label={`${t('personnel.firstName')} *`}><input value={form.prenom} onChange={e => setForm({...form, prenom:e.target.value})} required /></FormField>
                <FormField label={`${t('personnel.lastName')} *`}><input value={form.nom} onChange={e => setForm({...form, nom:e.target.value})} required /></FormField>
              </FormRow>
              <FormRow>
                <FormField label={`${t('personnel.post')} *`}><input value={form.poste} onChange={e => setForm({...form, poste:e.target.value})} required /></FormField>
                <FormField label={t('personnel.service')}>
                  <select value={form.service} onChange={e => setForm({...form, service:e.target.value})}>
                    {SERVICES.map(s => <option key={s}>{s}</option>)}
                  </select>
                </FormField>
              </FormRow>
            </div>
          </div>

          {/* ── SECTION A — Informations personnelles ── */}
          <div style={{ marginBottom:18, paddingBottom:14, borderBottom:'1px solid var(--gray-100)' }}>
            <h4 style={{ color:'var(--gold-dark)', fontWeight:700, fontSize:'0.73rem', textTransform:'uppercase', letterSpacing:'0.08em', marginBottom:12 }}>{t('personnel.sectionA')}</h4>
            <FormRow>
              <FormField label={t('personnel.firstName')}><input value={form.prenom} onChange={e => setForm({...form, prenom:e.target.value})} /></FormField>
              <FormField label={t('personnel.maidenName')}><input value={form.nom_jeune_fille} onChange={e => setForm({...form, nom_jeune_fille:e.target.value})} /></FormField>
            </FormRow>
            <FormRow>
              <FormField label={t('personnel.birthDate')}><input type="date" value={form.date_naissance} onChange={e => setForm({...form, date_naissance:e.target.value})} /></FormField>
              <FormField label={t('personnel.birthPlace')}><input value={form.lieu_naissance} onChange={e => setForm({...form, lieu_naissance:e.target.value})} /></FormField>
            </FormRow>
            <FormRow cols={1}>
              <FormField label={t('personnel.address')}><input value={form.adresse} onChange={e => setForm({...form, adresse:e.target.value})} /></FormField>
            </FormRow>
            <FormRow>
              <FormField label={t('personnel.phone')}><input value={form.telephone} onChange={e => setForm({...form, telephone:e.target.value})} /></FormField>
              <FormField label={t('personnel.email')}><input type="email" value={form.email} onChange={e => setForm({...form, email:e.target.value})} /></FormField>
            </FormRow>
            <FormRow>
              <FormField label={t('personnel.situation')}>
                <select value={form.situation_familiale} onChange={e => setForm({...form, situation_familiale:e.target.value})}>
                  {STATUTS_FAMILLE.map(s => <option key={s}>{s}</option>)}
                </select>
              </FormField>
              <div />
            </FormRow>
            <FormRow>
              <FormField label={t('personnel.emergencyName')}><input value={form.contact_urgence_nom} onChange={e => setForm({...form, contact_urgence_nom:e.target.value})} /></FormField>
              <FormField label={t('personnel.emergencyPhone')}><input value={form.contact_urgence_tel} onChange={e => setForm({...form, contact_urgence_tel:e.target.value})} /></FormField>
            </FormRow>
          </div>

          {/* ── SECTION B — CIN + Bancaire ── */}
          <div style={{ marginBottom:18, paddingBottom:14, borderBottom:'1px solid var(--gray-100)' }}>
            <h4 style={{ color:'var(--gold-dark)', fontWeight:700, fontSize:'0.73rem', textTransform:'uppercase', letterSpacing:'0.08em', marginBottom:12 }}>B — {t('personnel.cinNumber')} & {t('personnel.ribCode')}</h4>
            <FormRow>
              <FormField label={t('personnel.cinNumber')}><input value={form.cin_numero} onChange={e => setForm({...form, cin_numero:e.target.value})} placeholder="Ex: 101 234 567 890" /></FormField>
              <FormField label={t('personnel.cinDate')}><input type="date" value={form.cin_date} onChange={e => setForm({...form, cin_date:e.target.value})} /></FormField>
            </FormRow>
            <FormRow>
              <FormField label={t('personnel.cinPlace')}><input value={form.cin_lieu} onChange={e => setForm({...form, cin_lieu:e.target.value})} placeholder="Ex: Antananarivo" /></FormField>
              <div />
            </FormRow>
            <FormRow>
              <FormField label={t('personnel.ribCode')}><input value={form.rib_code} onChange={e => setForm({...form, rib_code:e.target.value})} placeholder="Ex: 00005 12345 01234567890 97" style={{ fontFamily:'monospace' }} /></FormField>
              <FormField label={t('personnel.bankName')}><input value={form.banque} onChange={e => setForm({...form, banque:e.target.value})} placeholder="Ex: BFV-SG, BOA, BNI..." /></FormField>
            </FormRow>
          </div>

          {/* ── SECTION C — Professionnel ── */}
          <div style={{ marginBottom:18, paddingBottom:14, borderBottom:'1px solid var(--gray-100)' }}>
            <h4 style={{ color:'var(--gold-dark)', fontWeight:700, fontSize:'0.73rem', textTransform:'uppercase', letterSpacing:'0.08em', marginBottom:12 }}>{t('personnel.sectionB')}</h4>
            <FormRow>
              <FormField label={t('personnel.contractType')}>
                <select value={form.type_contrat} onChange={e => setForm({...form, type_contrat:e.target.value})}>
                  {CONTRATS.map(c => <option key={c}>{c}</option>)}
                </select>
              </FormField>
              <FormField label={t('personnel.entryDate')}><input type="date" value={form.date_entree} onChange={e => setForm({...form, date_entree:e.target.value})} /></FormField>
            </FormRow>
            <FormRow>
              <FormField label={t('common.status')}>
                <select value={form.statut} onChange={e => setForm({...form, statut:e.target.value})}>
                  <option value="actif">{t('common.active')}</option>
                  <option value="inactif">{t('common.inactive')}</option>
                  <option value="suspendu">Suspendu / Suspended</option>
                </select>
              </FormField>
              <div />
            </FormRow>
          </div>

          {/* ── SECTION D — Administratif ── */}
          <div style={{ marginBottom:18, paddingBottom:14, borderBottom:'1px solid var(--gray-100)' }}>
            <h4 style={{ color:'var(--gold-dark)', fontWeight:700, fontSize:'0.73rem', textTransform:'uppercase', letterSpacing:'0.08em', marginBottom:12 }}>{t('personnel.sectionD')}</h4>
            <FormRow>
              <FormField label={t('personnel.cnaps')}><input value={form.cnaps} onChange={e => setForm({...form, cnaps:e.target.value})} /></FormField>
              <FormField label={t('personnel.aro')}><input value={form.aro} onChange={e => setForm({...form, aro:e.target.value})} /></FormField>
            </FormRow>
          </div>

          {/* ── SECTION E — Documents ── */}
          <div style={{ marginBottom:18 }}>
            <h4 style={{ color:'var(--gold-dark)', fontWeight:700, fontSize:'0.73rem', textTransform:'uppercase', letterSpacing:'0.08em', marginBottom:12 }}>{t('personnel.sectionE')} — {t('personnel.docSection')}</h4>
            <div style={{ display:'grid', gridTemplateColumns:'repeat(auto-fit, minmax(220px, 1fr))', gap:12 }}>
              <DocUpload label={t('personnel.diploma')} value={form.doc_diplome} onChange={v => setForm({...form, doc_diplome:v})} t={t} />
              <DocUpload label={t('personnel.cv')} value={form.doc_cv} onChange={v => setForm({...form, doc_cv:v})} t={t} />
              <DocUpload label={t('personnel.workContract')} value={form.doc_contrat} onChange={v => setForm({...form, doc_contrat:v})} t={t} />
            </div>
          </div>

          <div style={{ display:'flex', gap:10, justifyContent:'flex-end', paddingTop:18, borderTop:'1px solid var(--gray-100)', flexWrap:'wrap' }}>
            <Btn type="button" variant="secondary" onClick={() => setModalOpen(false)}>{t('common.cancel')}</Btn>
            {editing && <Btn type="button" variant="secondary" onClick={() => printFiche({...form, matricule:editing.matricule}, lang)}>🖨️ {t('personnel.printCard')}</Btn>}
            <Btn type="submit" variant="gold" disabled={saving}>
              {saving ? t('common.saving') : editing ? `💾 ${t('common.update')}` : t('personnel.newMember')}
            </Btn>
          </div>
        </form>
      </Modal>
    </div>
  );
}
